364		private function categorize_error( \Throwable $exception ): string {
365			$error_categories = array(
366				\ArgumentCountError::class       => 'arguments',
367				\TypeError::class                => 'type',
368				\InvalidArgumentException::class => 'validation',
369				\LogicException::class           => 'logic',
370				\RuntimeException::class         => 'execution',
371				\Error::class                    => 'system',
372			);
373	
374			foreach ( $error_categories as $class => $category ) {
375				if ( $exception instanceof $class ) {
